DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$DIR/../../.." && pwd)"
for tool in node npm; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    echo "  NOT RUN  mobile-headless: $tool is unavailable"
    exit 2
  fi
done
node "$ROOT/richos/mobile/test/run-suite.cjs" headless
# The iPhone/Android update-policy separation, watched going red one leak at a time (CEO ruling §91).
node "$ROOT/richos/mobile/test/policy-targets.mutation.mjs"
echo '  PASS  mobile headless core, CLI persistence/errors and resource packaging'
